import itertools,json
ad=[{2,6},{1,4,7},{6,7},{3,5},{1,6}]
bd=[{4,7},{2},{3,7},{4,5},{3,5,8}]
As=[a for a in itertools.product('K','MNP','LMQ','LNR','MNR') if len(set(a))==5]
Bs=[b for b in itertools.product('KLN','NPR','PQR','KMP','LPQ') if len(set(b))==5]
counts={}; witnesses={}
for a in As:
 for b in Bs:
  if a[1]!=b[3]: continue
  overlap=set(a)&set(b)
  if len(overlap)!=3 or len(overlap&set('KQR'))!=1: continue
  days={p:set() for p in 'KLMNPQR'}
  for p,d in zip(a,ad): days[p].update(d)
  for p,d in zip(b,bd): days[p].update(d)
  n=sum(len(d)>=3 for d in days.values())
  counts[n]=counts.get(n,0)+1
  witnesses.setdefault(n,dict(A=''.join(a),B=''.join(b)))
lo=min(counts);hi=max(counts)
print(json.dumps(dict(feasible_linkages=sum(counts.values()),bounds=[lo,hi],low_witness=witnesses[lo],high_witness=witnesses[hi],decision='confirmed' if lo>=3 else 'excluded' if hi<3 else 'undetermined')))
print(counts)

